function n(v) { if (v === '' || v == null) return null; const x = Number(String(v).replace(/\s/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.')); return Number.isFinite(x) ? x : null; }
function mul(a, b) { const x = n(a), y = n(b); return x != null && y != null ? x * y : null; }
export const toNum = n;

